import pytest

from fizzbuzz import fizzbuzz


def test_returns_list_of_str():
    result = fizzbuzz(15)
    assert isinstance(result, list)
    assert all(isinstance(item, str) for item in result)


def test_first_fifteen():
    assert fizzbuzz(15) == [
        "1", "2", "Fizz", "4", "Buzz",
        "Fizz", "7", "8", "Fizz", "Buzz",
        "11", "Fizz", "13", "14", "FizzBuzz",
    ]


def test_length_matches_n():
    for n in (0, 1, 5, 15, 100):
        assert len(fizzbuzz(n)) == max(n, 0)


def test_multiples_of_three_are_fizz():
    result = fizzbuzz(30)
    fizz_indices = {i for i in range(1, 31) if i % 3 == 0 and i % 5 != 0}
    actual = {i for i in range(1, 31) if result[i - 1] == "Fizz"}
    assert actual == fizz_indices


def test_multiples_of_five_are_buzz():
    result = fizzbuzz(30)
    buzz_indices = {i for i in range(1, 31) if i % 5 == 0 and i % 3 != 0}
    actual = {i for i in range(1, 31) if result[i - 1] == "Buzz"}
    assert actual == buzz_indices


def test_multiples_of_fifteen_are_fizzbuzz():
    result = fizzbuzz(45)
    assert [i for i in range(1, 46) if result[i - 1] == "FizzBuzz"] == [15, 30, 45]


def test_others_are_number_strings():
    result = fizzbuzz(10)
    plain = [i for i in range(1, 11) if i % 3 and i % 5]
    assert [result[i - 1] for i in plain] == [str(i) for i in plain]


@pytest.mark.parametrize(
    ("n", "expected"),
    [
        (0, []),
        (1, ["1"]),
        (2, ["1", "2"]),
        (3, ["1", "2", "Fizz"]),
        (5, ["1", "2", "Fizz", "4", "Buzz"]),
        (-3, []),
    ],
)
def test_small_values(n, expected):
    assert fizzbuzz(n) == expected


def test_fizzbuzz_counts_up_to_100():
    result = fizzbuzz(100)
    assert result.count("FizzBuzz") == 6
    assert result.count("Fizz") == 20
    assert result.count("Buzz") == 14
    assert result.count("100") == 1
EOF
